import React, { useEffect, useState } from 'react';
import axios from 'axios';

function AdminInvoices() {
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const token = localStorage.getItem('token');
  const headers = { Authorization: `Bearer ${token}` };

  useEffect(() => {
    const fetchInvoices = async () => {
      try {
        const res = await axios.get('/api/invoices/report', { headers });
        setInvoices(res.data.invoices || []);
      } catch (_) {}
      setLoading(false);
    };
    fetchInvoices();
  }, []);

  if (loading) return <p>Loading...</p>;

  return (
    <div style={{ padding: 20 }}>
      <h2>All Invoices</h2>
      {!invoices.length ? (
        <p>No invoices.</p>
      ) : (
        <>
          <ul>
            {invoices.map(inv => (
              <li key={inv._id} data-testid="invoice-row" onClick={() => window.location.hash = `#ainv-${inv._id}`}>
                {inv._id} — ${inv.total?.toFixed(2)} — {inv.status}
              </li>
            ))}
          </ul>
          {window.location.hash.startsWith('#ainv-') && (
            <div data-testid="invoice-detail" style={{ marginTop: 12 }}>
              Invoice Detail: {window.location.hash.replace('#ainv-', '')}
            </div>
          )}
        </>
      )}
    </div>
  );
}

export default AdminInvoices;
